impl ResponseCode {
    /// True for an `OK_*` code: the request succeeded.
    #[must_use]
    pub const fn is_ok(self) -> bool {
        matches!(
            self,
            Self::OK
                | Self::OKCertificateExpiresSoon
                | Self::OKNewSessionEstablished
                | Self::OKOldSessionJoined
                | Self::OKPowerToleranceConfirmed
        )
    }

    /// True for a `WARNING_*` code: the request succeeded, with a
    /// caveat the application should surface. The session continues.
    #[must_use]
    pub const fn is_warning(self) -> bool {
        matches!(
            self,
            Self::WARNINGAuthorizationSelectionInvalid
                | Self::WARNINGCertificateExpired
                | Self::WARNINGCertificateNotYetValid
                | Self::WARNINGCertificateRevoked
                | Self::WARNINGCertificateValidationError
                | Self::WARNINGChallengeInvalid
                | Self::WARNINGEIMAuthorizationFailure
                | Self::WARNINGEMSPUnknown
                | Self::WARNINGEVPowerProfileViolation
                | Self::WARNINGGeneralPnCAuthorizationError
                | Self::WARNINGNoCertificateAvailable
                | Self::WARNINGNoContractMatchingPCIDFound
                | Self::WARNINGPowerToleranceNotConfirmed
                | Self::WARNINGScheduleRenegotiationFailed
                | Self::WARNINGStandbyNotAllowed
                | Self::WARNINGWPT
        )
    }

    /// True for a `FAILED_*` code, which **ends the session**.
    ///
    /// ISO 15118 leaves no discretion here: after a failure response
    /// the only request left is `SessionStopReq`. The session cores
    /// enforce that; see `session::Flow::failed`.
    #[must_use]
    pub const fn is_failure(self) -> bool {
        matches!(
            self,
            Self::FAILED
                | Self::FAILEDAssociationError
                | Self::FAILEDContactorError
                | Self::FAILEDEVPowerProfileInvalid
                | Self::FAILEDEVPowerProfileViolation
                | Self::FAILEDMeteringSignatureNotValid
                | Self::FAILEDNoEnergyTransferServiceSelected
                | Self::FAILEDNoServiceRenegotiationSupported
                | Self::FAILEDPauseNotAllowed
                | Self::FAILEDPowerDeliveryNotApplied
                | Self::FAILEDPowerToleranceNotConfirmed
                | Self::FAILEDScheduleRenegotiation
                | Self::FAILEDScheduleSelectionInvalid
                | Self::FAILEDSequenceError
                | Self::FAILEDServiceIDInvalid
                | Self::FAILEDServiceSelectionInvalid
                | Self::FAILEDSignatureError
                | Self::FAILEDUnknownSession
                | Self::FAILEDWrongChargeParameter
        )
    }
}

/// Width of a document-level event code.
///
/// One alternative per global element in the schema set — 26 of them,
/// counting the imported schemas — plus the generic `SE(*)` and the
/// second-level group non-strict fidelity adds.
